const rawResponse = $input.first().json.text || '';
const initialInput = $('Set Initial Input').first().json;
const keyword = initialInput.keyword || '';

let parsedData = null;

try {
  let cleanText = rawResponse.trim();
  if (cleanText.startsWith('```json')) {
    cleanText = cleanText.replace(/^```json\s*/, '').replace(/```\s*$/, '');
  } else if (cleanText.startsWith('```')) {
    cleanText = cleanText.replace(/^```\s*/, '').replace(/```\s*$/, '');
  }
  parsedData = JSON.parse(cleanText);
} catch (e) {
  const jsonMatch = rawResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsedData = JSON.parse(jsonMatch[0]);
    } catch (err) {
      parsedData = null;
    }
  }
}

let title = '';
let meta_description = '';
let content = '';

if (parsedData && typeof parsedData === 'object') {
  title = parsedData.title || '';
  meta_description = parsedData.meta_description || '';
  content = parsedData.content || '';
}

// Fallback nếu model trả text không parse được JSON
if (!title) {
  const titleMatch = rawResponse.match(/(?:^#\s*|Title:\s*)([^\n]+)/i);
  title = titleMatch ? titleMatch[1].trim() : `${keyword} - Giải pháp toàn diện cho doanh nghiệp`;
}
if (!meta_description) {
  const metaMatch = rawResponse.match(/(?:Meta Description:\s*)([^\n]+)/i);
  meta_description = metaMatch ? metaMatch[1].trim() : `Tổng quan kiến thức và chiến lược về ${keyword}.`;
}
if (!content) {
  content = rawResponse;
}

return [{
  json: {
    keyword: keyword,
    title: title,
    meta_description: meta_description,
    content: content,
    generated_at: new Date().toISOString()
  }
}];
